import json
def f(g):
    # fill enclosed non-background cells with 4? demo: interior 0->4, border kept.
    H=len(g);W=len(g[0])
    out=[r[:] for r in g]
    seen=[[False]*W for _ in range(H)]
    stack=[(0,0)]
    seen[0][0]=True
    while stack:
        y,x=stack.pop()
        for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<H and 0<=nx<W and not seen[ny][nx]:
                seen[ny][nx]=True;stack.append((ny,nx))
    for y in range(H):
        for x in range(W):
            if not seen[y][x] and g[y][x]==0:
                out[y][x]=4
    return out
